import { ContextMenu, type ContextMenuSelectDetail } from '@absoluteui/components/context-menu';

const list = document.querySelector<HTMLUListElement>('#files');
if (list) {
  // The target gets no ARIA attributes: describe the menu so it is discoverable.
  const hint = document.createElement('p');
  hint.id = 'files-hint';
  hint.textContent = 'Right-click a file or press Shift+F10 for actions. The same actions are in each row\'s Actions button.';
  list.before(hint);
  list.setAttribute('aria-describedby', hint.id);
  ContextMenu.create(list, {
    label: 'File actions',
    items: [
      { id: 'rename', label: 'Rename' },
      { id: 'share', label: 'Share', items: [{ id: 'copy-link', label: 'Copy link' }] },
      { type: 'separator' },
      { id: 'delete', label: 'Delete', tone: 'danger' },
    ],
  });
  list.addEventListener('aui-select', (event) => {
    const { id, origin } = (event as CustomEvent<ContextMenuSelectDetail>).detail;
    const row = origin.closest<HTMLLIElement>('li[data-file]');
    if (row === null) return;
    row.dataset.lastAction = id;
  });
}

import { ContextMenu, type MenuItem } from '@absoluteui/components/context-menu';
import { Button } from '@absoluteui/components/button';

const canvas = document.createElement('div');
canvas.tabIndex = 0;
canvas.setAttribute('aria-label', 'Drawing');
const shape = document.createElement('button');
shape.type = 'button';
shape.dataset.shape = 'circle';
shape.textContent = 'Circle';
Button.enhance(shape, { variant: 'outline' });
canvas.append(shape);
document.body.append(canvas);

const shapeItems: MenuItem[] = [
  { id: 'bring-front', label: 'Bring to front' },
  { id: 'delete-shape', label: 'Delete shape', tone: 'danger' },
];
const canvasItems: MenuItem[] = [
  { id: 'paste', label: 'Paste', shortcut: 'Ctrl+V' },
  { type: 'checkbox', id: 'snap', label: 'Snap to grid', checked: true },
];
const menu = ContextMenu.create(canvas, { items: canvasItems });

// Capture phase runs before the component's own listener, so the right items are in place when it opens.
const chooseItems = (event: Event): void => {
  const onShape = event.target instanceof Element && event.target.closest('[data-shape]') !== null;
  menu.update({ items: onShape ? shapeItems : canvasItems });
};
canvas.addEventListener('contextmenu', chooseItems, { capture: true });
canvas.addEventListener('keydown', (event) => {
  if (event.key === 'ContextMenu' || (event.key === 'F10' && event.shiftKey)) chooseItems(event);
}, { capture: true });
